function normalizeBoard(b){b=b||{};const away=Array.isArray(b.away)&&b.away.length?b.away:defaultRivals();away.forEach(x=>{if(typeof x.onField!=='boolean')x.onField=true;});return {home:Array.isArray(b.home)?b.home:[],away,objects:Array.isArray(b.objects)?b.objects:[]};}
