function setupBenchDrag(){if(!tacticalCanMove()){return}let dragData=null;$$('.bench-player').forEach(el=>{el.ondragstart=e=>{dragData={team:el.dataset.team,id:el.dataset.id,name:el.dataset.name,number:el.dataset.number};e.dataTransfer.setData('text/plain','player')};el.onclick=e=>{if(el.dataset.team==='away'&&!e.target.closest('.bench-edit'))editRival(el.dataset.id)}});const pitch=$('#pitch');pitch.ondragover=e=>e.preventDefault();pitch.ondrop=e=>{e.preventDefault();if(!dragData)return;const r=pitch.getBoundingClientRect();placePlayer({...dragData,x:(e.clientX-r.left)/r.width*100,y:(e.clientY-r.top)/r.height*100});dragData=null;drawHomeBench($('.filter-btn.active')?.dataset.pos||'TODOS');drawRivals()}}
function setupBoard(){const pitch=$('#pitch');if(!pitch)return;pitch.oncontextmenu=e=>e.preventDefault();$$('.pitch-player',pitch).forEach(makePitchDraggable);$$('.training-object',pitch).forEach(makeTrainingObjectDraggable)}
function placeTrainingObject(o){const pitch=$('#pitch');if(!pitch)return;const el=document.createElement('div');el.className='training-object training-'+o.type;el.dataset.id=o.id;el.innerHTML=`<span>${trainingObjectIcon(o.type)}</span><button class="object-remove" title="Eliminar">×</button>${o.type==='minigoal'?'<button class="object-rotate-handle" title="Rotar">↻</button>':''}${o.type==='arrow'?'<button class="object-rotate-handle arrow-rotate" title="Rotar flecha">↻</button><button class="object-length-handle" title="Alargar flecha">↔</button>':''}`;el.style.left=(o.x??50)+'%';el.style.top=(o.y??50)+'%';el.style.setProperty('--rotation',(o.rotation||0)+'deg');el.style.setProperty('--arrow-length',Math.max(.45,Math.min(3,o.length||1)));pitch.appendChild(el);el.querySelector('.object-remove').onclick=e=>{e.stopPropagation();state.board.objects=(state.board.objects||[]).filter(x=>x.id!==o.id);el.remove()};el.onclick=e=>{if(e.target.closest('.object-remove,.object-rotate-handle'))return;$$('.training-object',pitch).forEach(x=>x.classList.remove('selected'));el.classList.add('selected')};el.onmousedown=e=>{if(e.target.closest('.object-remove,.object-rotate-handle'))return; if(!tacticalCanMove())return; makeTrainingObjectDraggable(el,e)};makeTrainingObjectDraggable(el);if(o.type==='minigoal')makeTrainingObjectRotatable(el,o);if(o.type==='arrow')makeTrainingArrowControls(el,o) }
function trainingObjectIcon(type){return trainingObjects.find(o=>o.key===type)?.icon||'•'}
function makeTrainingObjectDraggable(el,startEvent=null){if(!tacticalCanMove())return;let moving=false;const begin=e=>{if(e.target.closest('.object-remove,.object-rotate-handle'))return;e.preventDefault();moving=true;const r=$('#pitch').getBoundingClientRect();const move=ev=>{if(!moving)return;const xev=ev.touches?ev.touches[0]:ev,x=Math.max(2,Math.min(98,(xev.clientX-r.left)/r.width*100)),y=Math.max(4,Math.min(96,(xev.clientY-r.top)/r.height*100));el.style.left=x+'%';el.style.top=y+'%';const o=(state.board.objects||[]).find(z=>z.id===el.dataset.id);if(o){o.x=x;o.y=y}};const up=()=>{moving=false;document.removeEventListener('mousemove',move);document.removeEventListener('mouseup',up);document.removeEventListener('touchmove',move)};document.addEventListener('mousemove',move);document.addEventListener('mouseup',up);document.addEventListener('touchmove',move,{passive:false})};el.onmousedown=begin;if(startEvent)begin(startEvent)}
function makeTrainingObjectRotatable(el,o){if(o.type!=='minigoal')return;const handle=el.querySelector('.object-rotate-handle');const apply=angle=>{o.rotation=((Math.round(angle)%360)+360)%360;el.style.setProperty('--rotation',o.rotation+'deg')};el.addEventListener('wheel',e=>{if(!tacticalCanMove()||!el.classList.contains('selected'))return;e.preventDefault();apply((o.rotation||0)+(e.deltaY>0?10:-10))},{passive:false});if(!handle)return;handle.onmousedown=e=>{e.stopPropagation();e.preventDefault();el.classList.add('selected');const move=ev=>{const pt=ev.touches?ev.touches[0]:ev;const r=el.getBoundingClientRect();const cx=r.left+r.width/2,cy=r.top+r.height/2;let angle=Math.atan2(pt.clientY-cy,pt.clientX-cx)*180/Math.PI+90;apply(angle)};const up=()=>{document.removeEventListener('mousemove',move);document.removeEventListener('mouseup',up)};document.addEventListener('mousemove',move);document.addEventListener('mouseup',up)}}
function makeTrainingArrowControls(el,o){
 if(o.type!=='arrow')return;
 const rotateHandle=el.querySelector('.arrow-rotate');
 const lengthHandle=el.querySelector('.object-length-handle');
 const applyRotation=angle=>{o.rotation=((Math.round(angle)%360)+360)%360;el.style.setProperty('--rotation',o.rotation+'deg')};
 const applyLength=value=>{o.length=Math.max(.45,Math.min(3,value));el.style.setProperty('--arrow-length',o.length)};
 const center=()=>{const r=el.getBoundingClientRect();return {x:r.left+r.width/2,y:r.top+r.height/2}};
 const startRotate=e=>{if(!tacticalCanMove())return;e.preventDefault();e.stopPropagation();el.classList.add('selected');const move=ev=>{const pt=ev.touches?ev.touches[0]:ev,c=center();applyRotation(Math.atan2(pt.clientY-c.y,pt.clientX-c.x)*180/Math.PI)};const up=()=>{document.removeEventListener('mousemove',move);document.removeEventListener('mouseup',up);document.removeEventListener('touchmove',move)};document.addEventListener('mousemove',move);document.addEventListener('mouseup',up);document.addEventListener('touchmove',move,{passive:false})};
 const startLength=e=>{if(!tacticalCanMove())return;e.preventDefault();e.stopPropagation();el.classList.add('selected');const move=ev=>{const pt=ev.touches?ev.touches[0]:ev,c=center(),dx=pt.clientX-c.x,dy=pt.clientY-c.y,angle=(o.rotation||0)*Math.PI/180,along=dx*Math.cos(angle)+dy*Math.sin(angle),base=Math.max(28,el.getBoundingClientRect().width/2);applyLength(Math.max(.45,Math.min(3,Math.abs(along)/base)))};const up=()=>{document.removeEventListener('mousemove',move);document.removeEventListener('mouseup',up);document.removeEventListener('touchmove',move)};document.addEventListener('mousemove',move);document.addEventListener('mouseup',up);document.addEventListener('touchmove',move,{passive:false})};
 rotateHandle?.addEventListener('mousedown',startRotate);rotateHandle?.addEventListener('touchstart',startRotate,{passive:false});lengthHandle?.addEventListener('mousedown',startLength);lengthHandle?.addEventListener('touchstart',startLength,{passive:false});
 el.addEventListener('wheel',e=>{if(!tacticalCanMove()||!el.classList.contains('selected'))return;e.preventDefault();applyRotation((o.rotation||0)+(e.deltaY>0?10:-10))},{passive:false});
}
function clearMaterials(){if(!tacticalCanMove())return;state.board.objects=[];$$('.training-object').forEach(x=>x.remove());toast('Materiales retirados del campo')}

function renderTacticPlayersOnly(){renderBoard();drawHomeBench('TODOS');drawRivals()}
function placePlayer(p){const arr=state.board[p.team];if(!arr)return;p.onField=true;let old=arr.find(x=>String(x.id)===String(p.id));if(old){Object.assign(old,p)}else arr.push({...p});let el=$(`.pitch-player[data-team="${p.team}"][data-id="${p.id}"]`);if(!el){el=document.createElement('div');el.className='pitch-player '+(p.team==='away'?'rival':'');el.dataset.team=p.team;el.dataset.id=p.id;el.innerHTML=`<span>${esc(p.number)}</span><small>${esc(p.name)}</small><button class="remove-on-field" title="Devolver al banquillo">×</button>`;$('#pitch').appendChild(el);makePitchDraggable(el);el.querySelector('.remove-on-field').onclick=e=>{e.stopPropagation();removeFromPitch(p.team,p.id)}}el.style.left=p.x+'%';el.style.top=p.y+'%';}
function makePitchDraggable(el){if(!tacticalCanMove())return;let moving=false;const move=e=>{if(!moving)return;const r=$('#pitch').getBoundingClientRect(),pt=e.touches?e.touches[0]:e;const x=Math.max(2,Math.min(98,(pt.clientX-r.left)/r.width*100)),y=Math.max(4,Math.min(96,(pt.clientY-r.top)/r.height*100));el.style.left=x+'%';el.style.top=y+'%';const a=state.board[el.dataset.team].find(z=>String(z.id)===el.dataset.id);if(a){a.x=x;a.y=y}};const up=()=>{moving=false;document.removeEventListener('mousemove',move);document.removeEventListener('mouseup',up)};el.onmousedown=e=>{if(e.target.closest('button'))return;e.preventDefault();moving=true;document.addEventListener('mousemove',move);document.addEventListener('mouseup',up)};el.ondblclick=()=>{if(el.dataset.team==='away')editRival(el.dataset.id)}}
function removeFromPitch(team,id){const a=(state.board[team]||[]).find(z=>String(z.id)===String(id));if(a)a.onField=false;$(`.pitch-player[data-team="${team}"][data-id="${id}"]`)?.remove();if(team==='home')drawHomeBench($('.filter-btn.active')?.dataset.pos||'TODOS');else drawRivals();renderMobileTacticLists()}
function clearTeam(team){if(!tacticalCanMove())return;if(team==='away'){(state.board.away||[]).forEach(x=>x.onField=false)}else{(state.board.home||[]).forEach(x=>x.onField=false)};$$(`.pitch-player[data-team="${team}"]`).forEach(x=>x.remove());if(team==='home')drawHomeBench('TODOS');else drawRivals();renderMobileTacticLists()}
function editRival(id){if(!canEdit())return;const p=state.board.away.find(x=>String(x.id)===String(id));if(!p)return;modal(`<div class="modal-head"><h2>Editar rival</h2><button class="close">×</button></div><form id="rival-form"><div class="form-grid"><div class="field"><label>Nombre / posición</label><input name="name" value="${esc(p.name)}" required></div><div class="field"><label>Número</label><input name="number" value="${esc(p.number)}" maxlength="2"></div></div><div class="actions modal-actions"><button class="btn primary">Guardar</button><button type="button" class="btn danger" id="delete-rival">Eliminar jugador rival</button></div></form>`);$('.close').onclick=closeModal;$('#rival-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));p.name=d.name;p.number=d.number||'?';closeModal();renderBoard();drawRivals()};$('#delete-rival').onclick=()=>{state.board.away=state.board.away.filter(x=>String(x.id)!==String(id));$(`.pitch-player[data-team="away"][data-id="${id}"]`)?.remove();closeModal();drawRivals()}}
async function saveTactic(){if(!canEdit())return;const name=$('#tactic-name').value.trim();if(!name)return toast('Pon un nombre a la táctica');await api('/tactics',{method:'POST',body:JSON.stringify({name,payload:JSON.stringify(state.board)})});toast('Táctica guardada');navigate('tactics')}
refreshAuth().then(()=>navigate('dashboard')).catch(e=>{$('#content').innerHTML=`<div class="card"><h2>No se pudo cargar</h2><p class="muted">${esc(e.message)}</p></div>`});
